export function createShopPages({ BASE, icon, fragrances, formatPrice, esc }) {
  const L = (lang, de, en) => lang === 'de' ? de : en;
  const path = (lang, route = '') => `${BASE}/${lang}/${route}`;
  const orderedScents = ['aloe', 'argan', 'bamboo'].filter(id => fragrances.includes(id));
  const price = (format, lang) => formatPrice(format === 'refill' ? 450 : 1250, lang);
  const asset = name => `${BASE}/assets/${name}`;
  const detour = (kind, scent = '', format = '', target = '') => `data-detour="${kind}"${scent ? ` data-detour-scent="${scent}"` : ''}${format ? ` data-detour-format="${format}"` : ''}${target ? ` data-detour-target="${target}"` : ''}`;
  const contextualAttributes = href => href.includes('/assembly/') ? detour('inspect') : href.includes('/refill/') ? detour('refill') : href.includes('/story/') ? detour('materials') : href.includes('/faq/') ? detour('faq') : '';
  const button = (href, label, modifier = '', attributes = contextualAttributes(href)) => `<a class="button ${modifier}" href="${href}" ${attributes}><span>${label}</span>${icon('arrow')}</a>`;
  const link = (href, label, attributes = contextualAttributes(href)) => `<a class="text-link" href="${href}" ${attributes}><span>${label}</span>${icon('arrow')}</a>`;
  const eyebrow = text => `<p class="eyebrow">${text}</p>`;
  const image = (name, alt, eager = false, cls = '') => `<img class="${cls}" src="${asset(name)}" alt="${esc(alt)}" width="1024" height="1280" ${eager ? 'fetchpriority="high" loading="eager"' : 'loading="lazy"'} decoding="async">`;

  function viewer(lang, mode = 'product', scent = 'bamboo', cls = '', eager = false, direction = 'detail') {
    const filename = mode === 'refill' ? `shop-refill-${scent}.webp` : mode === 'cap' ? 'shop-cap.webp' : 'shop-product.webp';
    const alt = L(lang,
      mode === 'refill' ? 'Transparenter PET-Einsatz mit gefülltem Shampoo und Siegelfolie' : mode === 'cap' ? 'Silikon-Dosierkappe mit ringgelagerter Verschlusslasche' : 'Bamboo Shampoo: Bambushülle, Silikonkappe und gefüllter PET-Einsatz',
      mode === 'refill' ? 'Transparent PET insert filled with shampoo and sealed with film' : mode === 'cap' ? 'Silicone dosing cap with a ring-mounted closure' : 'Bamboo Shampoo: bamboo shell, silicone cap and filled PET insert');
    return `<div class="shop-scene ${cls}" data-shop-scene="${mode}" data-art-direction="${direction}" data-scent="${scent}" role="group" aria-label="${esc(alt)}">${image(filename, alt, eager, 'shop-scene__fallback')}</div>`;
  }

  function scentCards(lang, format = 'shampoo', selected = orderedScents) {
    const t = shopCopy[lang];
    return selected.map(id => {
      const href = path(lang, `products/${id}/`) + (format === 'refill' ? '?format=refill' : '');
      const label = format === 'refill' ? 'Refill' : 'Shampoo';
      return `<article class="product-card scent-${id}" data-reveal data-format="${format}" data-fragrance="${id}">
        <a class="product-card__art" href="${href}" ${detour('product', id, format)} aria-label="${esc(`${t.names[id]} ${label}, 250 ml — ${L(lang, 'ansehen', 'view')}`)}">
          <div class="product-card__meta"><span>${label.toUpperCase()}</span><span>250 ML</span></div>
          <span class="product-card__world" aria-hidden="true">${t.names[id]}</span>
          ${image(format === 'refill' ? `shop-refill-${id}.webp` : 'shop-product.webp', `${t.names[id]} ${label} · 250 ml`)}
          <span class="product-card__scent">${t.scentWords[id]}</span>
          <span class="product-card__arrow" aria-hidden="true">${icon('arrow')}</span>
        </a>
        <div class="product-card__info"><h3><a href="${href}" ${detour('product', id, format)}>${t.names[id]}<span>${label}</span></a></h3><strong class="product-card__price">${price(format, lang)}</strong></div>
        <div class="product-card__bottom">${link(href, L(lang, 'Entdecken', 'Discover'), detour('product', id, format))}<button class="product-card__add" type="button" data-add="${id}" data-id="${id}" data-format="${format}" data-quick-add="${id}" data-quick-format="${format}" aria-label="${esc(`${t.names[id]} ${label} ${L(lang, 'in die Tasche', 'add to bag')}`)}">${icon('plus')}</button></div>
      </article>`;
    }).join('');
  }

  function accordions(items, prefix = 'answer') {
    return items.map(([question, answer], index) => `<details class="accordion" id="${prefix}-${index}"><summary><span>${question}</span>${icon('plus')}</summary><div class="accordion__body">${answer}</div></details>`).join('');
  }

  function closing(lang, inJourney = false) {
    return `<section class="closing-cta section-shell"><div data-reveal>${eyebrow(L(lang, 'DEIN DUFT. DEIN FORMAT.', 'YOUR SCENT. YOUR FORMAT.'))}<h2 class="display">${L(lang, 'FINDE DEINEN<br>BAMBOO.', 'FIND YOUR<br>BAMBOO.')}</h2></div><div class="closing-cta__action"><p>${L(lang, 'Aloe, Argan oder Bamboo.<br>Starte mit der Hülle. Bleib beim Refill.', 'Aloe, Argan or Bamboo.<br>Start with the shell. Stay for the refill.')}</p>${button(inJourney ? '#collection' : path(lang, 'shop/'), L(lang, 'Duft auswählen', 'Choose your scent'))}</div></section>`;
  }

  function ritual(lang, variant = 'home') {
    const steps = lang === 'de' ? [
      ['ALLES DRIN.', 'Bambushülle, Silikonkappe und ein gefüllter Einsatz. Die Siegelfolie hält das neue Refill geschlossen.'],
      ['PEEL IT.', 'Kappe abnehmen. Die Siegelfolie lösen und vollständig vom Rand abziehen.'],
      ['PRESS. POUR.', 'Kappe aufsetzen, die Verschlusslasche öffnen und zur Seite drehen. Die flexible Silikonmitte gehört zur Kappe.'],
      ['REFILL IT.', 'Kappe abnehmen. Den leeren PET-Einsatz herausnehmen und ein neues Refill einsetzen.'],
      ['GO AGAIN.', 'Bambushülle und Silikonkappe bleiben. Das neue Refill ist bis zur nächsten Verwendung versiegelt.']
    ] : [
      ['ALL IN.', 'Bamboo shell, silicone cap and a filled insert. The film keeps the new refill sealed.'],
      ['PEEL IT.', 'Take the cap off. Lift the film seal and peel it completely off the rim.'],
      ['PRESS. POUR.', 'Put the cap back on, open the closure and turn it aside. The flexible silicone centre is part of the cap.'],
      ['REFILL IT.', 'Take the cap off. Remove the empty PET insert and put a new refill in.'],
      ['GO AGAIN.', 'Keep the bamboo shell and silicone cap. The new refill stays sealed until its next use.']
    ];
    return `<section class="ritual-scroll ritual-scroll--${variant}" ${variant === 'home' ? 'id="ritual" data-journey-chapter="ritual"' : ''} data-ritual-scroll aria-label="${L(lang, 'Das Produkt vom ersten Öffnen bis zum nächsten Refill', 'The product from first opening to the next refill')}">
      <div class="ritual-sticky">
        <div class="ritual-stage" data-shop-scene="ritual" data-scent="bamboo" role="group" aria-label="${L(lang, '3D-Animation: öffnen, Siegelfolie abziehen, dosieren und PET-Einsatz wechseln', '3D animation: open, peel the film, dose and replace the PET insert')}">${image('shop-product.webp', L(lang, 'Bamboo Shampoo in der geschlossenen Produktansicht', 'Bamboo Shampoo in its closed product view'))}</div>
        <div class="ritual-copy" data-ritual-copy>
          ${eyebrow(L(lang, 'DAS SYSTEM IN BEWEGUNG', 'THE SYSTEM IN MOTION'))}
          <div class="ritual-panels">${steps.map(([title, body], index) => `<div class="ritual-step ${index === 0 ? 'is-active' : ''}" data-ritual-step="${index}"><h2 class="display">${title}</h2><p>${body}</p></div>`).join('')}</div>
          <div class="ritual-progress" aria-hidden="true"><span></span></div>
          <p class="ritual-instruction">${icon('down')}<span>${L(lang, 'Scrollen bewegt das Produkt', 'Scroll to move the product')}</span></p>
          <div class="ritual-actions"><a class="text-link" href="${path(lang, 'story/')}" data-ritual-detail ${detour('materials')}><span data-ritual-detail-label>${L(lang, 'Aufbau ansehen', 'See the construction')}</span>${icon('arrow')}</a>${link(`${BASE}/assembly/`, L(lang, 'Genau ansehen', 'Inspect closely'), `${detour('inspect', '', '', 'current')} data-ritual-inspect`)}</div>
        </div>
        <span class="ritual-background-word" aria-hidden="true">REPEAT</span>
      </div>
    </section>`;
  }

  function home(lang) {
    const t = shopCopy[lang];
    const chapters = lang === 'de' ? [['discover', 'Entdecken'], ['materials', 'Aufbau'], ['ritual', 'Ritual'], ['collection', 'Auswählen'], ['questions', 'Fragen']] : [['discover', 'Discover'], ['materials', 'Construction'], ['ritual', 'Ritual'], ['collection', 'Choose'], ['questions', 'Questions']];
    return `<main id="main" data-journey>
      <section class="campaign-hero scent-bamboo" id="discover" data-journey-chapter="discover" data-world="bamboo" data-world-kind="product">
        <div class="campaign-atmosphere" aria-hidden="true"></div>
        <div class="campaign-topline">${eyebrow('SHAMPOO, REDESIGNED.')}<span>250 ML / ALOE · ARGAN · BAMBOO</span></div>
        <h1 class="campaign-word">BAMBOO<span class="sr-only"> Shampoo</span></h1>
        ${viewer(lang, 'product', 'bamboo', 'campaign-product', true, 'campaign')}
        <div class="campaign-deck">
          <div class="campaign-world-copy"><p class="eyebrow">${L(lang, 'DEIN DUFT', 'YOUR SCENT')}</p><h2 data-world-name>Bamboo</h2><p data-world-description>${t.scentDescriptions.bamboo}</p></div>
          <div class="campaign-switch" role="group" aria-label="${L(lang, 'Duftwelt wählen', 'Choose a scent world')}">${orderedScents.map(id => `<button class="world-choice scent-${id}" type="button" data-world-scent="${id}" aria-pressed="${id === 'bamboo'}"><span class="world-choice__swatch" aria-hidden="true"></span><span>${t.names[id]}</span></button>`).join('')}</div>
          <div class="campaign-purchase"><p>${L(lang, 'Shampoo + Bambushülle', 'Shampoo + bamboo shell')}<strong>${price('shampoo', lang)}</strong></p><a class="button" href="${path(lang, 'products/bamboo/')}" data-world-link data-detour="product"><span>${L(lang, 'Duft entdecken', 'Explore this scent')}</span>${icon('arrow')}</a></div>
        </div>
        <a class="campaign-scroll" href="#materials" aria-label="${L(lang, 'Den Aufbau entdecken', 'Explore the construction')}">${icon('down')}</a>
      </section>
      <nav class="journey-nav" data-journey-nav aria-label="${L(lang, 'Dein Weg durch Bamboo Shampoo', 'Your Bamboo Shampoo journey')}"><div class="journey-nav__chapters">${chapters.map(([id, name], index) => `<a href="#${id}" data-journey-link="${id}" ${index === 0 ? 'aria-current="location"' : ''}><span>${name}</span></a>`).join('')}</div><a class="journey-nav__choose" href="#collection">${L(lang, 'Duft wählen', 'Choose a scent')}${icon('arrow')}</a></nav>
      <section class="water-campaign materials-chapter" id="materials" data-journey-chapter="materials" aria-labelledby="materials-title">
        <div class="water-campaign__image" data-parallax="0.06"><img src="${asset('bamboo-water.webp')}" width="1536" height="1024" alt="${L(lang, 'Bambushalme in einer surrealen, lavendelfarbenen Wasserlandschaft', 'Bamboo stems in a surreal lavender water landscape')}" loading="lazy" decoding="async"></div>
        <div class="water-campaign__copy" data-reveal>${eyebrow('BAMBOO / SILICONE / PET')}<h2 class="display" id="materials-title">${L(lang, 'DIE HÜLLE<br>BLEIBT.', 'THE SHELL<br>STAYS.')}</h2><p>${L(lang, 'Bambushülle. Flexible Silikonkappe. Austauschbarer PET-Einsatz. Drei Teile, die zusammenpassen.', 'Bamboo shell. Flexible silicone cap. Replaceable PET insert. Three parts designed to fit.')}</p>${button(path(lang, 'story/'), L(lang, 'Die Details entdecken', 'Explore the details'))}</div>
        <div class="materials-strip"><a href="${path(lang, 'story/')}" ${detour('materials')}><strong>BAMBOO</strong><span>${L(lang, 'Die Hülle bleibt.', 'The shell stays.')}</span>${icon('arrow')}</a><a href="${BASE}/assembly/" ${detour('inspect', '', '', 'dose')}><strong>SILICONE</strong><span>${L(lang, 'Drücken. Dosieren.', 'Press. Dose.')}</span>${icon('arrow')}</a><a href="${path(lang, 'refill/')}" ${detour('refill')}><strong>PET / 250 ML</strong><span>${L(lang, 'Einsatz wechseln.', 'Replace the insert.')}</span>${icon('arrow')}</a></div>
      </section>
      ${ritual(lang)}
      <section class="section-shell home-collection" id="collection" data-journey-chapter="collection">
        <div class="section-heading" data-reveal><div>${eyebrow(L(lang, 'DIE KOLLEKTION', 'THE COLLECTION'))}<h2 class="display">${L(lang, 'DREI DÜFTE.<br>DEIN BAMBOO.', 'THREE MOODS.<br>YOUR BAMBOO.')}</h2></div><div class="section-heading__aside"><p>${L(lang, '250 ml. Bambus außen, Shampoo innen.<br>Entdecke den Duft, der zu dir passt.', '250 ml. Bamboo outside, shampoo inside.<br>Find the scent that fits you.')}</p>${link(path(lang, 'shop/'), L(lang, 'Alle Produkte', 'All products'))}</div></div>
        <div class="collection-grid collection-grid--campaign">${scentCards(lang)}</div>
        <div class="section-end"><span class="collection-format-note">${L(lang, 'Shampoo + Hülle', 'Shampoo + shell')} ${formatPrice(1250, lang)} · Refill ${formatPrice(450, lang)}</span></div>
      </section>
      <section class="section-shell faq-tease" id="questions" data-journey-chapter="questions"><div class="section-heading" data-reveal><div>${eyebrow(L(lang, 'GUT ZU WISSEN', 'GOOD TO KNOW'))}<h2 class="display">${L(lang, 'GUTE FRAGEN.<br>KLARE ANTWORTEN.', 'GOOD QUESTIONS.<br>CLEAR ANSWERS.')}</h2></div>${link(path(lang, 'faq/'), L(lang, 'Alle Antworten', 'All the answers'))}</div><div class="faq-list">${accordions(faqItems(lang).slice(0, 3), 'home-answer')}</div></section>
      ${closing(lang, true)}
    </main>`;
  }

  function collection(lang) {
    const t = shopCopy[lang];
    return `<main id="main" class="catalog-page">
      <section class="section-shell collection-intro"><div data-reveal>${eyebrow(L(lang, 'DIE KOLLEKTION / 250 ML', 'THE COLLECTION / 250 ML'))}<h1 class="display">${L(lang, 'DEIN DUFT.<br>DEIN FORMAT.', 'YOUR SCENT.<br>YOUR FORMAT.')}</h1></div><div class="collection-intro__aside"><p>${L(lang, 'Starte mit Bambushülle und Kappe.<br>Mach mit dem Refill weiter.', 'Start with the bamboo shell and cap.<br>Come back for a refill.')}</p><div class="collection-intro__prices"><span>${t.shampoo}<strong>${formatPrice(1250, lang)}</strong></span><span>Refill<strong>${formatPrice(450, lang)}</strong></span></div></div></section>
      <section class="section-shell collection-products" aria-label="${L(lang, 'Produkte', 'Products')}">
        <div class="collection-toolbar"><div class="collection-filters" role="group" aria-label="${L(lang, 'Nach Format filtern', 'Filter by format')}"><button class="is-active" type="button" data-filter="all" aria-pressed="true">${L(lang, 'Alle', 'All')}<span>6</span></button><button type="button" data-filter="shampoo" aria-pressed="false">Shampoo<span>3</span></button><button type="button" data-filter="refill" aria-pressed="false">Refill<span>3</span></button></div><span class="collection-count" data-result-count aria-live="polite">6 ${t.filterResults}</span></div>
        <div class="collection-grid collection-grid--shop">${scentCards(lang, 'shampoo')}${scentCards(lang, 'refill')}</div>
      </section>
      <section class="format-chapter section-shell"><h2 class="display" data-reveal">${L(lang, 'HÜLLE BEHALTEN.<br>DUFT NACHLEGEN.', 'KEEP THE SHELL.<br>REFILL THE SCENT.')}</h2><div data-reveal><p>${L(lang, 'Beim Refill ersetzt du den PET-Einsatz. Bambushülle und Silikonkappe bleiben bei dir.', 'A refill replaces the PET insert. The bamboo shell and silicone cap stay with you.')}</p>${button(path(lang, 'refill/'), L(lang, 'Das Refill-System', 'Explore the refill system'))}</div></section>
    </main>`;
  }

  function refill(lang) {
    const t = shopCopy[lang];
    return `<main id="main">
      <section class="campaign-hero campaign-hero--refill scent-argan">
        <div class="campaign-atmosphere" aria-hidden="true"></div><div class="campaign-topline">${eyebrow('KEEP. REFILL. REPEAT.')}<span>250 ML / ${formatPrice(1800, lang)} / L</span></div>
        <h1 class="campaign-word">REFILL<span class="sr-only"> ${L(lang, 'für Bamboo Shampoo', 'for Bamboo Shampoo')}</span></h1>
        ${viewer(lang, 'refill', 'bamboo', 'campaign-product campaign-product--refill', true, 'campaign')}
        <div class="campaign-deck campaign-deck--refill"><div class="campaign-world-copy"><h2>${L(lang, 'Die Hülle bleibt.', 'The shell stays.')}</h2><p>${L(lang, 'Ein neues Refill. Dieselbe Bambushülle und Kappe.', 'A new refill. The same bamboo shell and cap.')}</p></div><div class="campaign-purchase"><p>250 ml<strong>${price('refill', lang)}</strong></p>${button('#refill-scents', L(lang, 'Refill auswählen', 'Choose a refill'))}</div></div>
        <a class="campaign-scroll" href="#refill-scents" aria-label="${L(lang, 'Refill-Düfte ansehen', 'View refill scents')}">${icon('down')}</a>
      </section>
      <section class="section-shell refill-selection" id="refill-scents"><div class="section-heading" data-reveal><div>${eyebrow(L(lang, 'DEIN NÄCHSTES REFILL', 'YOUR NEXT REFILL'))}<h2 class="display">${L(lang, 'GLEICHER DUFT.<br>ODER EIN NEUER.', 'SAME SCENT.<br>OR SOMETHING NEW.')}</h2></div><div class="section-heading__aside"><p>Aloe / Argan / Bamboo<br>250 ml · ${price('refill', lang)}</p>${link(`${BASE}/assembly/`, L(lang, 'Wechsel im Vollbild', 'Watch the change fullscreen'))}</div></div><div class="collection-grid collection-grid--campaign">${scentCards(lang, 'refill')}</div></section>
      <div id="refill-ritual">${ritual(lang, 'refill')}</div>
      <section class="gel-chapter"><img src="${asset('gel-macro.webp')}" width="1536" height="1024" alt="${L(lang, 'Grapefruitfarbene Gelfalten auf einer roséfarbenen Oberfläche als Texturstudie', 'Grapefruit-coloured gel folds on a rose surface, a texture study')}" loading="lazy" decoding="async"><div class="gel-chapter__copy" data-reveal>${eyebrow('FRESH INSIDE.')}<h2 class="display">${L(lang, 'PASST REIN.<br>GEHT WEITER.', 'FITS INSIDE.<br>GOES AGAIN.')}</h2><p>${L(lang, 'Dünnes, transparentes PET. Ein Auflagerand, der auf der Bambushülle sitzt. Und eine Folie, die vor der Verwendung abgezogen wird.', 'Thin, transparent PET. A support flange that rests on the bamboo shell. And a film that peels off before use.')}</p></div><span class="gel-chapter__caption">${L(lang, 'TEXTURSTUDIE / 250 ML', 'TEXTURE STUDY / 250 ML')}</span></section>
      <section class="section-shell refill-practical"><div class="section-heading" data-reveal><div>${eyebrow(L(lang, 'DER WECHSEL', 'THE CHANGE'))}<h2 class="display">${L(lang, 'AUF. RAUS.<br>NEU REIN.', 'OPEN. OUT.<br>NEW ONE IN.')}</h2></div><p>${L(lang, 'Die Siegelfolie vor der Verwendung vollständig entfernen.', 'Remove the film seal completely before use.')}</p></div><ol class="process-list"><li><span>${icon('minus')}</span><div><h3>${L(lang, 'Öffnen & entnehmen', 'Open & remove')}</h3><p>${L(lang, 'Kappe abnehmen und den leeren PET-Einsatz aus der Bambushülle ziehen.', 'Take off the cap and lift the empty PET insert out of the bamboo shell.')}</p></div></li><li><span>${icon('plus')}</span><div><h3>${L(lang, 'Neu einsetzen', 'Put the new one in')}</h3><p>${L(lang, 'Das neue Refill einsetzen. Sein oberer Rand liegt auf dem Tubusrand auf.', 'Put the new refill in. Its upper flange rests on the tube rim.')}</p></div></li><li><span>${icon('arrow')}</span><div><h3>${L(lang, 'Abziehen & aufsetzen', 'Peel & replace')}</h3><p>${L(lang, 'Vor der Verwendung die Folie abziehen. Dann die Silikonkappe wieder aufsetzen.', 'Before use, peel off the film. Then put the silicone cap back on.')}</p></div></li></ol></section>
      ${closing(lang)}
    </main>`;
  }

  function productForm(lang, id) {
    const t = shopCopy[lang];
    return `<form class="product-form" data-product-form data-id="${id}" data-default-format="shampoo">
      <input type="hidden" name="scent" value="${id}">
      <fieldset><legend>${L(lang, 'Format', 'Format')}</legend><div class="format-options">
        <label class="format-option"><input type="radio" name="format" value="shampoo" checked><span><span class="format-option__head"><strong>${t.shampoo}</strong><b>${formatPrice(1250, lang)}</b></span><small>250 ml · ${L(lang, 'Hülle, Kappe & gefüllter Einsatz', 'Shell, cap & filled insert')}</small></span></label>
        <label class="format-option"><input type="radio" name="format" value="refill"><span><span class="format-option__head"><strong>Refill</strong><b>${formatPrice(450, lang)}</b></span><small>250 ml · ${L(lang, 'Gefüllter PET-Einsatz mit Siegelfolie', 'Filled PET insert with film seal')}</small></span></label>
      </div></fieldset>
      <fieldset><legend>${L(lang, 'Duft', 'Scent')}<span data-scent-name>${t.names[id]}</span></legend><div class="scent-options">${orderedScents.map(scent => `<a class="scent-option scent-${scent} ${scent === id ? 'is-current' : ''}" data-scent-link href="${path(lang, `products/${scent}/`)}" ${scent === id ? 'aria-current="page"' : ''}><i class="scent-dot" aria-hidden="true"></i><span>${t.names[scent]}</span></a>`).join('')}</div></fieldset>
      <div class="product-price-line"><strong class="product-price" data-product-price data-price aria-label="${t.productPriceLabel}">${formatPrice(1250, lang)}</strong><span class="unit-price"><span data-unit-price>${formatPrice(5000, lang)}</span> / l · 250 ml</span></div>
      <div class="product-add-line"><div class="quantity-control"><button type="button" data-quantity="-1" disabled aria-label="${L(lang, 'Menge reduzieren', 'Decrease quantity')}">${icon('minus')}</button><input name="quantity" type="number" min="1" max="20" value="1" inputmode="numeric" aria-label="${t.quantity}"><button type="button" data-quantity="1" aria-label="${L(lang, 'Menge erhöhen', 'Increase quantity')}">${icon('plus')}</button></div><button class="button product-add" type="submit"><span data-add-label>${t.formatAdd.shampoo}</span>${icon('bag')}</button></div>
      <p class="product-format-note" data-format-note>${t.formatNote.shampoo}</p>
      <div class="product-dock" data-product-dock><div><span data-product-dock-label>${t.names[id]} / 250 ml</span><strong data-product-price>${formatPrice(1250, lang)}</strong></div><button class="button" type="submit"><span>${t.add}</span>${icon('bag')}</button></div>
    </form>`;
  }

  function productGallery(lang, id = 'bamboo', eager = false) {
    const t = shopCopy[lang];
    return `<div class="product-gallery"><div class="product-gallery__primary"><span class="product-gallery__word" data-gallery-scent aria-hidden="true">${t.names[id]}</span>${viewer(lang, 'product', id, 'product-viewer', eager, 'detail')}<span class="product-gallery__volume">250 ML</span></div><div class="product-gallery__views" role="group" aria-label="${L(lang, 'Produktansicht wählen', 'Choose a product view')}">${['product', 'refill', 'cap'].map(mode => `<button class="gallery-view ${mode === 'product' ? 'is-active' : ''}" type="button" data-gallery-view="${mode}" aria-pressed="${mode === 'product'}">${image(mode === 'refill' ? `shop-refill-${id}.webp` : mode === 'cap' ? 'shop-cap.webp' : 'shop-product.webp', '')}<span>${t.productGallery[mode]}</span></button>`).join('')}</div><p class="product-gallery__hint">${L(lang, 'Ziehen zum Drehen', 'Drag to rotate')}</p></div>`;
  }

  function product(lang, id) {
    const t = shopCopy[lang];
    const acc = lang === 'de' ? [
      ['Was ist enthalten?', '<p>Shampoo + Hülle: Bambushülle, wiederverwendbare Silikonkappe und ein gefüllter 250-ml-PET-Einsatz mit Siegelfolie.</p><p>Refill: ein gefüllter 250-ml-PET-Einsatz mit Siegelfolie. Die vorhandene Hülle und Kappe werden weiterverwendet.</p>'],
      ['Wie funktioniert die Kappe?', '<p>Die Mitte ist Teil der flexiblen Silikonkappe. Beim Drücken gibt die Oberfläche nach. Die ringgelagerte Verschlusslasche wird aus der Öffnung gelöst und zur Seite gedreht.</p>'],
      ['Duft & Inhaltsstoffe', `<p>${t.scentDescriptions[id]}</p><p>Die vollständige Inhaltsstoffliste und verbindliche Anwendungshinweise werden vor Verkaufsstart ergänzt.</p>`],
      ['Was bleibt beim Refill?', '<p>Bambushülle und Silikonkappe. Der leere PET-Einsatz wird entnommen. Der neue Einsatz sitzt mit seinem oberen Rand auf dem Tubusrand. Seine Siegelfolie wird vor der Verwendung vollständig abgezogen.</p>']
    ] : [
      ['What is included?', '<p>Shampoo + shell: bamboo shell, reusable silicone cap and a filled 250 ml PET insert with a film seal.</p><p>Refill: one filled 250 ml PET insert with a film seal. Your existing shell and cap are reused.</p>'],
      ['How does the cap work?', '<p>The centre is part of the flexible silicone cap. The surface yields when pressed. The ring-mounted closure lifts out of the opening and turns aside.</p>'],
      ['Scent & ingredients', `<p>${t.scentDescriptions[id]}</p><p>The full ingredient list and final directions will be added before sales begin.</p>`],
      ['What do I keep for a refill?', '<p>The bamboo shell and silicone cap. Remove the empty PET insert. The new insert rests on the tube rim with its upper flange. Remove its film seal completely before use.</p>']
    ];
    return `<main id="main" class="pdp-page scent-${id}">
      <nav class="breadcrumb section-shell" aria-label="${L(lang, 'Seitenpfad', 'Breadcrumb')}"><a href="${path(lang)}">${t.home}</a><span aria-hidden="true">/</span><a href="${path(lang, 'shop/')}">Shop</a><span aria-hidden="true">/</span><span aria-current="page">${t.names[id]}</span></nav>
      <section class="product-layout section-shell">
        ${productGallery(lang, id, true)}
        <div class="product-config"><div>${eyebrow('BAMBOO SHAMPOO / 250 ML')}<h1 class="display" data-detail-scent>${t.names[id]}</h1><p class="scent-subtitle">${t.scentWords[id]}</p><p class="product-scent-copy">${t.scentDescriptions[id]}</p></div>${productForm(lang, id)}<div class="product-details faq-list" id="product-details">${accordions(acc, `${id}-detail`)}</div></div>
      </section>
      <section class="format-chapter section-shell"><h2 class="display" data-reveal">${L(lang, 'DEIN BAMBOO.<br>IMMER WIEDER.', 'YOUR BAMBOO.<br>AGAIN AND AGAIN.')}</h2><div data-reveal><p>${L(lang, '250 ml im transparenten PET-Einsatz. Deine Hülle und die Dosierkappe bleiben für das nächste Refill.', '250 ml in a transparent PET insert. Your shell and dosing cap stay for the next refill.')}</p>${button(path(lang, 'refill/'), L(lang, 'Das Refill-System', 'Explore the refill system'))}</div></section>
      ${ritual(lang, 'product')}
      <section class="section-shell related-products"><div class="section-heading" data-reveal><div>${eyebrow(L(lang, 'MEHR ENTDECKEN', 'EXPLORE MORE'))}<h2 class="display">${L(lang, 'DIE ANDEREN<br>BEIDEN.', 'MEET THE<br>OTHER TWO.')}</h2></div>${link(path(lang, 'shop/'), L(lang, 'Die ganze Kollektion', 'The full collection'))}</div><div class="collection-grid collection-grid--two">${scentCards(lang, 'shampoo', orderedScents.filter(scent => scent !== id))}</div></section>
    </main>`;
  }

  function story(lang) {
    return `<main id="main" class="story-page">
      <section class="section-shell story-intro"><div data-reveal>${eyebrow('BAMBOO / SILICONE / PET')}<h1 class="display">${L(lang, 'DREI TEILE.<br>EIN BAMBOO.', 'THREE PARTS.<br>ONE BAMBOO.')}</h1></div><p class="lede" data-reveal>${L(lang, 'Die Hülle bleibt. Der Einsatz wechselt. Dazwischen: Details, die genau zusammenpassen.', 'The shell stays. The insert changes. Between them: details designed to fit.')}</p></section>
      <section class="story-product-stage scent-bamboo">${viewer(lang, 'product', 'bamboo', 'story-product', true, 'campaign')}<span class="story-product-stage__word" aria-hidden="true">KEEP IT.</span><a class="text-link" href="${BASE}/assembly/" ${detour('inspect')}><span>${L(lang, 'Die Konstruktion in Bewegung', 'See the construction in motion')}</span>${icon('arrow')}</a></section>
      <section class="section-shell story-components"><div class="component-list">
        <article class="component-row" data-reveal><div class="component-row__copy">${eyebrow('BAMBOO')}<h2 class="display">${L(lang, 'DIE HÜLLE.', 'THE SHELL.')}</h2><p>${L(lang, 'Bambus mit gelaserter Gravur. Der zylindrische Tubus nimmt den PET-Einsatz auf. Oben schließen Kappe und Rand bündig aneinander an.', 'Bamboo with laser engraving. The cylindrical tube holds the PET insert. At the top, the cap meets the rim in a flush fit.')}</p><p class="component-row__caption">${L(lang, 'FÜR DAS NÄCHSTE REFILL BEHALTEN', 'KEEP FOR THE NEXT REFILL')}</p></div><figure class="component-row__art scent-bamboo">${image('shop-product.webp', L(lang, 'Originale Bambushülle mit Lasergravur und bündig aufgesetzter Silikonkappe', 'Original bamboo shell with laser engraving and a flush silicone cap'))}</figure></article>
        <article class="component-row component-row--reverse" data-reveal><div class="component-row__copy">${eyebrow('SILICONE')}<h2 class="display">${L(lang, 'DIE KAPPE.', 'THE CAP.')}</h2><p>${L(lang, 'Die Mitte ist Teil der Kappe. Beim Drücken biegt sich die Silikonoberfläche. Der kreisrunde Ring lässt die Verschlusslasche um die Mitte schwenken.', 'The centre is part of the cap. Pressing it bends the silicone surface. The circular ring lets the closure swivel around the centre.')}</p><p class="component-row__caption">PRESS TO DOSE.</p></div><figure class="component-row__art scent-argan">${viewer(lang, 'cap', 'bamboo', 'component-viewer')}</figure></article>
        <article class="component-row" data-reveal><div class="component-row__copy">${eyebrow('PET / 250 ML')}<h2 class="display">${L(lang, 'DAS REFILL.', 'THE REFILL.')}</h2><p>${L(lang, 'Dünn und transparent. Der umlaufende obere Rand liegt auf der Bambushülle auf. Darauf sitzt die Folie, die vor der Verwendung vollständig abgezogen wird.', 'Thin and transparent. The upper flange rests on the bamboo shell. It holds the film that peels off completely before use.')}</p>${link(path(lang, 'refill/'), L(lang, 'Der nächste Einsatz', 'Meet your next insert'))}</div><figure class="component-row__art scent-aloe">${viewer(lang, 'refill', 'bamboo', 'component-viewer')}</figure></article>
      </div></section>
      ${closing(lang)}
    </main>`;
  }

  function faqItems(lang) {
    return lang === 'de' ? [
      ['Welche Düfte gibt es?', '<p>Aloe, Argan und Bamboo. Jeder Duft ist als Shampoo mit Bambushülle und als 250-ml-Refill vorgesehen.</p>'],
      ['Was bekomme ich beim ersten Kauf?', `<p>Für ${formatPrice(1250, lang)}: Bambushülle, wiederverwendbare Silikonkappe und ein gefüllter 250-ml-PET-Einsatz mit abziehbarer Siegelfolie.</p>`],
      ['Was kostet ein Refill — und was ist enthalten?', `<p>Ein 250-ml-Refill kostet ${formatPrice(450, lang)}. Es besteht aus dem gefüllten, transparenten PET-Einsatz mit Siegelfolie. Deine Bambushülle und Kappe verwendest du weiter.</p>`],
      ['Wie wechsle ich den Einsatz?', `<p>Kappe abnehmen, den leeren Einsatz entnehmen und das neue Refill einsetzen. Den Folienverschluss vor der Verwendung vollständig abziehen und die vorhandene Kappe wieder aufsetzen.</p><p>${link(path(lang, 'refill/'), 'Den Refill-Wechsel erleben')}</p>`],
      ['Ist das Refill eine flexible Nachfüllpackung?', '<p>Es ist ein dünner, transparenter PET-Einsatz, der direkt in die Bambushülle passt. Sein oberer Rand liegt auf dem Tubusrand auf und trägt die Siegelfolie.</p>'],
      ['Wie öffnet sich die Dosierkappe?', '<p>Die Verschlusslasche wird aus der Öffnung gelöst und zur Seite gedreht. Ihr Ring kann sich um die Mitte bewegen. Die flexible Mitte selbst gehört zur Silikonkappe und biegt die Oberfläche beim Drücken.</p>'],
      ['Wo finde ich die Inhaltsstoffe?', '<p>Aloe, Argan und Bamboo sind die Namen der Düfte. Die vollständigen Inhaltsstofflisten und finalen Anwendungshinweise werden vor Verkaufsstart ergänzt.</p>'],
      ['Kann ich in dieser Vorschau bestellen?', '<p>Du kannst Produkte auswählen, Mengen ändern und deine Tasche prüfen. Diese GitHub.io-Vorschau nimmt keine Bestellungen oder Zahlungen an und fragt keine Kundendaten ab.</p>'],
      ['Wo wird meine Auswahl gespeichert?', '<p>Deine Auswahl bleibt für diese Browsersitzung lokal im Browser. Es gibt dafür kein Kundenkonto. Ohne Browserspeicher funktioniert die Tasche während des geöffneten Besuchs weiter.</p>']
    ] : [
      ['Which scents are available?', '<p>Aloe, Argan and Bamboo. Each scent is presented as shampoo with the bamboo shell and as a 250 ml refill.</p>'],
      ['What comes with my first purchase?', `<p>For ${formatPrice(1250, lang)}: the bamboo shell, reusable silicone cap and a filled 250 ml PET insert with a peel-off film seal.</p>`],
      ['How much is a refill — and what is included?', `<p>A 250 ml refill costs ${formatPrice(450, lang)}. It contains the filled, transparent PET insert with a film seal. Your bamboo shell and cap are reused.</p>`],
      ['How do I replace the insert?', `<p>Take off the cap, remove the empty insert and put the new refill in. Peel off the film seal completely before use, then put your existing cap back on.</p><p>${link(path(lang, 'refill/'), 'Watch the refill change')}</p>`],
      ['Is the refill a flexible refill pouch?', '<p>It is a thin, transparent PET insert that fits directly inside the bamboo shell. Its upper flange rests on the tube rim and holds the film seal.</p>'],
      ['How does the dosing cap open?', '<p>The closure lifts out of the opening and turns aside. Its ring can rotate around the centre. The flexible centre itself belongs to the silicone cap and bends the surface when pressed.</p>'],
      ['Where can I find the ingredients?', '<p>Aloe, Argan and Bamboo are the scent names. Full ingredient lists and final directions will be added before sales begin.</p>'],
      ['Can I order from this preview?', '<p>You can choose products, change quantities and review your bag. This GitHub.io preview does not accept orders or payments and does not ask for customer information.</p>'],
      ['Where is my selection saved?', '<p>Your selection stays locally in the browser for this browsing session. There is no customer account. If browser storage is unavailable, the bag still works during the open visit.</p>']
    ];
  }

  function faq(lang) {
    return `<main id="main" class="faq-page"><section class="section-shell faq-intro"><div data-reveal>${eyebrow(L(lang, 'FRAGEN & ANTWORTEN', 'QUESTIONS & ANSWERS'))}<h1 class="display">${L(lang, 'GUT ZU<br>WISSEN.', 'GOOD TO<br>KNOW.')}</h1></div><p class="lede" data-reveal>${L(lang, 'Düfte, Formate und die Details des Refill-Systems. Hier findest du die Antworten.', 'Scents, formats and the details of the refill system. Here are the answers.')}</p></section><section class="section-shell faq-layout"><aside class="faq-aside">${eyebrow('KEEP. REFILL. REPEAT.')}<p>${L(lang, 'Sieh das Produkt in Bewegung — vom ersten Öffnen bis zum nächsten Einsatz.', 'See the product in motion — from its first opening to the next insert.')}</p>${link(path(lang, 'refill/'), L(lang, 'Zum Refill-System', 'Explore the refill system'))}${link(path(lang, 'shop/'), L(lang, 'Zur Kollektion', 'Explore the collection'))}</aside><div class="faq-list">${accordions(faqItems(lang), 'faq-answer')}</div></section>${closing(lang)}</main>`;
  }

  function checkout(lang) {
    return `<main id="main" class="checkout-page"><section class="section-shell checkout-intro"><div>${eyebrow(L(lang, 'DEINE AUSWAHL', 'YOUR SELECTION'))}<h1 class="display">${L(lang, 'DEINE<br>TASCHE.', 'YOUR<br>BAG.')}</h1></div><p class="lede">${L(lang, 'Düfte, Formate und Mengen auf einen Blick. Diese Vorschau nimmt keine Bestellungen oder Zahlungen an.', 'Scents, formats and quantities at a glance. This preview does not accept orders or payments.')}</p></section><section class="section-shell checkout-layout" id="cart-review"><div class="review-items" data-review-items aria-live="polite"><div class="review-empty"><h2>${L(lang, 'Noch Platz für deinen Duft.', 'Room for your scent.')}</h2><p>${L(lang, 'Deine Produktauswahl erscheint hier.', 'Your product selection appears here.')}</p>${button(path(lang, 'shop/'), L(lang, 'Die Kollektion entdecken', 'Explore the collection'))}</div></div><aside class="review-summary" aria-labelledby="review-summary-title">${eyebrow('BAMBOO SHAMPOO')}<h2 id="review-summary-title">${L(lang, 'Deine Übersicht', 'Your overview')}</h2><div class="review-total"><span>${L(lang, 'Gesamtsumme', 'Total')}</span><strong data-review-total>${formatPrice(0, lang)}</strong></div><p>${L(lang, 'Produktpreise der Vorschau. Kein Bestellabschluss, keine Zahlung und keine Eingabe von Kundendaten.', 'Preview product prices. No order submission, payment or customer information entry.')}</p>${button(path(lang, 'shop/'), L(lang, 'Weiter entdecken', 'Keep exploring'))}${link(path(lang, 'refill/'), L(lang, 'Mehr über Refills', 'More about refills'))}</aside></section></main>`;
  }

  function detours(lang) {
    const t = shopCopy[lang];
    const ingredients = faqItems(lang)[6];
    const contents = lang === 'de' ? [
      ['Was ist enthalten?', '<p>Shampoo + Hülle: Bambushülle, Silikonkappe und gefüllter 250-ml-PET-Einsatz mit Siegelfolie. Refill: der gefüllte PET-Einsatz mit Siegelfolie, für deine vorhandene Hülle und Kappe.</p>'],
      ingredients
    ] : [
      ['What is included?', '<p>Shampoo + shell: bamboo shell, silicone cap and filled 250 ml PET insert with a film seal. Refill: the filled PET insert with a film seal, for your existing shell and cap.</p>'],
      ingredients
    ];
    return `<dialog class="journey-dialog" id="journey-dialog" aria-labelledby="detour-title">
      <div class="journey-dialog__shell">
        <header class="journey-dialog__header"><button class="detour-return" type="button" data-detour-close autofocus>${icon('arrow')}<span>${L(lang, 'Zurück zum Entdecken', 'Back to exploring')}</span></button><h2 id="detour-title" data-detour-title>${L(lang, 'Dein Bamboo', 'Your Bamboo')}</h2><button class="icon-button detour-close" type="button" data-detour-close aria-label="${t.close}">${icon('close')}</button></header>
        <div class="journey-dialog__body" data-detour-body>
          <section class="detour-panel detour-product scent-bamboo" data-detour-panel="product" data-detour-product hidden>
            <div class="detour-product__layout product-layout">
              ${productGallery(lang)}
              <div class="product-config"><div>${eyebrow('BAMBOO SHAMPOO / 250 ML')}<h3 class="display" data-detour-product-name data-detail-scent>Bamboo</h3><p class="scent-subtitle" data-detour-product-words data-detail-words>${t.scentWords.bamboo}</p><p class="product-scent-copy" data-detour-product-description data-detail-description>${t.scentDescriptions.bamboo}</p></div>${productForm(lang, 'bamboo')}<div class="detour-add-feedback" data-detour-feedback hidden><p role="status" aria-live="polite" data-product-status></p><button class="text-link" type="button" data-open-bag>${L(lang, 'Meine Tasche ansehen', 'View my bag')}${icon('bag')}</button></div><a class="text-link detour-product__page" href="${path(lang, 'products/bamboo/')}" data-native-route data-product-page-link><span>${L(lang, 'Produktseite öffnen', 'Open product page')}</span>${icon('arrow')}</a><div class="product-details faq-list">${accordions(contents, 'detour-product-answer')}</div></div>
            </div>
          </section>
          <section class="detour-panel detour-materials scent-bamboo" data-detour-panel="materials" hidden>
            <div class="detour-split">
              ${productGallery(lang)}
              <div class="detour-copy">${eyebrow('BAMBOO / SILICONE / PET')}<h3 class="display">${L(lang, 'DREI TEILE.<br>EIN SYSTEM.', 'THREE PARTS.<br>ONE SYSTEM.')}</h3><dl class="material-facts">
                <div><dt>${L(lang, 'Bambushülle', 'Bamboo shell')}</dt><dd>${L(lang, 'Nimmt den Einsatz auf. Die Lasergravur bleibt. Kappe und Tubusrand schließen bündig an.', 'Holds the insert. The laser engraving stays. The cap meets the tube rim in a flush fit.')}</dd></div>
                <div><dt>${L(lang, 'Silikonkappe', 'Silicone cap')}</dt><dd>${L(lang, 'Die flexible Mitte gehört zur Kappe. Der kreisrunde Ring lässt die Verschlusslasche zur Seite schwenken.', 'The flexible centre is part of the cap. The circular ring lets the closure swivel aside.')}</dd></div>
                <div><dt>${L(lang, 'PET-Einsatz', 'PET insert')}</dt><dd>${L(lang, 'Dünne, transparente Wand. Der obere Auflagerand sitzt auf dem Tubusrand und trägt die abziehbare Siegelfolie.', 'Thin, transparent walls. The upper flange rests on the tube rim and holds the peel-off film seal.')}</dd></div>
              </dl><div class="detour-actions">${button(`${BASE}/assembly/`, L(lang, 'Genau ansehen', 'Inspect closely'), '', detour('inspect', '', '', 'closed'))}${link(path(lang, 'refill/'), L(lang, 'Was beim Refill bleibt', 'What stays for a refill'))}</div></div>
            </div>
          </section>
          <section class="detour-panel detour-refill scent-bamboo" data-detour-panel="refill" hidden>
            <div class="detour-split">
              <div class="detour-refill__art"><span class="detour-refill__word" aria-hidden="true">REFILL</span>${viewer(lang, 'refill', 'bamboo', 'detour-refill__viewer')}</div>
              <div class="detour-copy">${eyebrow('KEEP. REFILL. REPEAT.')}<h3 class="display">${L(lang, 'NEU DRIN.<br>WEITER GEHT’S.', 'NEW INSIDE.<br>GO AGAIN.')}</h3><p class="detour-refill__price">250 ml <strong>${price('refill', lang)}</strong></p><ol class="detour-process">
                <li><strong>${L(lang, 'Öffnen & entnehmen', 'Open & remove')}</strong><p>${L(lang, 'Kappe abnehmen. Den leeren PET-Einsatz aus der Bambushülle ziehen.', 'Take off the cap. Lift the empty PET insert out of the bamboo shell.')}</p></li>
                <li><strong>${L(lang, 'Neu einsetzen', 'Put the new one in')}</strong><p>${L(lang, 'Das neue Refill einsetzen. Sein oberer Rand liegt auf dem Tubusrand auf.', 'Put the new refill in. Its upper flange rests on the tube rim.')}</p></li>
                <li><strong>${L(lang, 'Abziehen & aufsetzen', 'Peel & replace')}</strong><p>${L(lang, 'Vor der Verwendung die Siegelfolie vollständig abziehen. Die vorhandene Silikonkappe wieder aufsetzen.', 'Before use, peel the film seal off completely. Put your existing silicone cap back on.')}</p></li>
              </ol><div class="detour-actions">${button(path(lang, 'products/bamboo/') + '?format=refill', L(lang, 'Mein Refill auswählen', 'Choose my refill'), '', detour('product', '', 'refill'))}${link(`${BASE}/assembly/`, L(lang, 'Wechsel genau ansehen', 'Inspect the change'), detour('inspect', '', '', 'refill'))}</div></div>
            </div>
          </section>
          <section class="detour-panel detour-faq" data-detour-panel="faq" hidden><div class="detour-faq__intro">${eyebrow(L(lang, 'FRAGEN & ANTWORTEN', 'QUESTIONS & ANSWERS'))}<h3 class="display">${L(lang, 'GUT ZU<br>WISSEN.', 'GOOD TO<br>KNOW.')}</h3></div><div class="faq-list">${accordions(faqItems(lang), 'detour-faq-answer')}</div></section>
          <section class="detour-panel detour-inspect scent-bamboo" data-detour-panel="inspect" hidden>
            <div class="inspection-stage" data-shop-scene="ritual" data-scent="bamboo" data-inspection role="group" aria-label="${L(lang, 'Produkt in 3D untersuchen: drehen und zoomen', 'Inspect the product in 3D: rotate and zoom')}">${image('shop-product.webp', L(lang, 'Bamboo Shampoo mit Originalgravur und Dosierkappe', 'Bamboo Shampoo with original engraving and dosing cap'))}</div>
            <div class="inspection-toolbar"><p>${L(lang, 'Ziehen zum Drehen · Pinchen zum Zoomen', 'Drag to rotate · Pinch to zoom')}</p><div class="inspection-zoom" role="group" aria-label="${L(lang, 'Ansicht vergrößern oder zurücksetzen', 'Zoom or reset the view')}"><button type="button" data-inspect-zoom="out" aria-label="${L(lang, 'Verkleinern', 'Zoom out')}">${icon('minus')}</button><button type="button" data-inspect-zoom="in" aria-label="${L(lang, 'Vergrößern', 'Zoom in')}">${icon('plus')}</button><button class="inspection-reset" type="button" data-inspect-zoom="reset">${L(lang, 'Ansicht zurücksetzen', 'Reset view')}</button></div></div>
            <label class="inspection-timeline" for="inspection-progress"><span>${L(lang, 'Vom Öffnen zum Refill', 'From opening to refill')}</span><input id="inspection-progress" type="range" min="0" max="1" step="0.001" value="0" data-inspect-progress aria-label="${L(lang, 'Produktanimation vorwärts und rückwärts bewegen', 'Move the product animation forward and backward')}"></label>
          </section>
        </div>
      </div>
    </dialog>`;
  }

  const withReturn = (lang, body) => body.replace(/<main\b[^>]*>/, opening => `${opening}<a class="journey-resume" href="${path(lang)}?resume=1" data-resume-journey hidden><span>${L(lang, 'Entdecken fortsetzen', 'Resume your journey')}</span>${icon('arrow')}</a>`);
  return Object.fromEntries(['de', 'en'].map(lang => [lang, {
    home: home(lang), collection: withReturn(lang, collection(lang)), refill: withReturn(lang, refill(lang)),
    story: withReturn(lang, story(lang)), faq: withReturn(lang, faq(lang)), checkout: withReturn(lang, checkout(lang)), detours: detours(lang),
    products: Object.fromEntries(orderedScents.map(id => [id, withReturn(lang, product(lang, id))]))
  }]));
}
